import pdfplumber
import pandas as pd
import json
import re

def clean_currency(x):
    if isinstance(x, str):
        return float(re.sub(r'[^\d.]', '', x))
    return float(x)

def clean_text(x):
    if isinstance(x, str):
        return x.strip()
    return x

def extract_pdf_data(pdf_path):
    data = []
    with pdfplumber.open(pdf_path) as pdf:
        for page in pdf.pages:
            table = page.extract_table()
            if table:
                # Assuming first row on first page is header, but subsequent pages might not have it or might repeat it
                # The OCR output showed headers on page 1. Let's handle headers dynamically.
                # Actually pdfplumber extract_table usually returns a list of lists.
                for row in table:
                    # Basic cleaning of row elements (remove None)
                    clean_row = [str(item) if item is not None else "" for item in row]
                    # Check if it's a header row
                    if clean_row[0] == "ID" and clean_row[1] == "First":
                         continue

                    # Ensure row has enough columns (9 columns based on visual check)
                    if len(clean_row) >= 9:
                        # Extract fields
                        # ID First Last Dept Position Salary Years Location Score
                        emp = {
                            "ID": clean_row[0],
                            "First": clean_row[1],
                            "Last": clean_row[2],
                            "Dept": clean_row[3],
                            "Position": clean_row[4],
                            "Salary": clean_currency(clean_row[5]),
                            "Years": float(clean_row[6]) if clean_row[6] else 0,
                            "Location": clean_row[7],
                            "Score": float(clean_row[8]) if clean_row[8] else 0.0
                        }
                        data.append(emp)
    return pd.DataFrame(data)

def main():
    pdf_path = '/root/employees_backup.pdf'
    xlsx_path = '/root/employees_current.xlsx'
    output_path = '/root/diff_report.json'

    # 1. Read PDF
    try:
        df_pdf = extract_pdf_data(pdf_path)
    except Exception as e:
        print(f"Error reading PDF: {e}")
        return

    # 2. Read Excel
    try:
        df_xlsx = pd.read_excel(xlsx_path)
    except Exception as e:
        print(f"Error reading Excel: {e}")
        return

    # Normalize Excel columns to match PDF keys for comparison
    # Expected columns: ID, First, Last, Dept, Position, Salary, Years, Location, Score
    # Check Excel columns
    # print("Excel columns:", df_xlsx.columns)

    # Ensure ID is string
    df_pdf['ID'] = df_pdf['ID'].astype(str)
    df_xlsx['ID'] = df_xlsx['ID'].astype(str)

    # Set ID as index for easier comparison
    df_pdf.set_index('ID', inplace=True)
    df_xlsx.set_index('ID', inplace=True)

    # 3. Identify Deleted Employees (In PDF but not in Excel)
    deleted_ids = list(set(df_pdf.index) - set(df_xlsx.index))
    deleted_ids.sort()

    # 4. Identify Modified Employees
    modified_employees = []

    # Only compare IDs that exist in both
    common_ids = list(set(df_pdf.index).intersection(set(df_xlsx.index)))
    common_ids.sort()

    for emp_id in common_ids:
        pdf_row = df_pdf.loc[emp_id]
        xlsx_row = df_xlsx.loc[emp_id]

        # Columns to compare
        columns = ['First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']

        for col in columns:
            if col not in xlsx_row:
                continue # Skip if column missing in Excel

            val_pdf = pdf_row[col]
            val_xlsx = xlsx_row[col]

            # Normalize for comparison
            # Handle numbers
            if col in ['Salary', 'Years', 'Score']:
                try:
                    val_pdf = float(val_pdf)
                    val_xlsx = float(val_xlsx)
                    # Check for equality with tolerance for floats
                    if abs(val_pdf - val_xlsx) > 0.001:
                         modified_employees.append({
                            "id": emp_id,
                            "field": col,
                            "old_value": val_pdf,
                            "new_value": val_xlsx
                        })
                except:
                    # If conversion fails, compare as strings
                    if str(val_pdf) != str(val_xlsx):
                         modified_employees.append({
                            "id": emp_id,
                            "field": col,
                            "old_value": val_pdf,
                            "new_value": val_xlsx
                        })
            else:
                # Strings
                if str(val_pdf).strip() != str(val_xlsx).strip():
                    modified_employees.append({
                        "id": emp_id,
                        "field": col,
                        "old_value": str(val_pdf).strip(),
                        "new_value": str(val_xlsx).strip()
                    })

    # Sort modified employees by ID
    modified_employees.sort(key=lambda x: x['id'])

    # 5. Generate Report
    report = {
        "deleted_employees": deleted_ids,
        "modified_employees": modified_employees
    }

    with open(output_path, 'w') as f:
        json.dump(report, f, indent=2)

    print("Diff report generated.")

if __name__ == "__main__":
    main()
